(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Chuỗi vocal của mọi thời kỳ.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Một plugin.</span>","hero.cycle":"Một plugin.|Trên giọng hát của bạn.|Trong mọi DAW.","hero.sub":"Tìm một nghệ sĩ, chọn một thời kỳ, nhấn play. Takelight nạp trọn chuỗi vocal — chỉnh cao độ, EQ, nén, khử xì, delay, reverb và bus vocal — dựng từ chính các mô-đun của nó. Ngoại tuyến và 100% không AI.","price.note":"Hiện chưa có gì để bán. Từ phiên bản 1.0, Freally Takelight sẽ được bán dưới dạng giấy phép trả một lần, có bản dùng thử miễn phí toàn bộ plugin trước đó.","hero.chipStandalone":"Ứng dụng độc lập","what.title":"Đây là gì","what.p1":"Một giọng hát thô không nghe giống bản thu, và khoảng cách đó là một chuỗi: tuning, EQ, bộ nén, bộ khử âm xì, delay và reverb trên send, cùng một bus vocal, đúng thứ tự, đúng thiết lập.","what.p2":"Takelight giữ trọn một chuỗi cho mỗi nghệ sĩ và mỗi thời kỳ trong một plugin duy nhất, dựng từ chính các mô-đun của nó, nên bạn không bao giờ cần plugin nào khác để nghe nó.","what.p3":"Nạp một chuỗi và nó chuyển vào mượt mà, không một tiếng tách. Định hình nó bằng bốn macro, hoặc mở rack và vặn bất kỳ núm nào.","features.title":"Bên trong có gì","featuresPage.cards.chains.title":"Chuỗi theo nghệ sĩ và thời kỳ","featuresPage.cards.chains.body":"Gõ tên một nghệ sĩ, chọn thời kỳ và vai trò — Giọng chính hoặc Ad-lib — và cả chuỗi nạp theo thứ tự: insert, kênh return hiệu ứng và bus vocal.","featuresPage.cards.swap.title":"Đổi chuỗi không tiếng tách","featuresPage.cards.swap.body":"Đổi chuỗi khi bài đang chạy. Chuỗi mới được chuẩn bị tách khỏi âm thanh và chuyển vào trong 30 mili giây, nên không có gì kêu lụp bụp.","featuresPage.cards.joint.title":"Joint","featuresPage.cards.joint.body":"Một rack chứa cả chuỗi: chỉnh cao độ, bốn loại EQ, sáu loại bộ nén, bộ khử âm xì, gate, bão hòa, exciter, lo-fi, bộ giới hạn, doubler, chorus, flanger, phaser, tự động pan, delay, reverb, bốn kênh return và một bus vocal.","featuresPage.cards.modes.title":"Đơn giản và Nâng cao","featuresPage.cards.modes.body":"Đơn giản hiển thị bốn macro — Chỉnh cao độ, Âm sắc, Không gian và Mức độ. Nâng cao hiển thị mọi mô-đun dưới dạng phần cứng được render, mỗi thẻ vẽ ra việc mô-đun của nó làm — đường cong EQ trên giọng hát của bạn, đường cong của bộ nén và mức nó giảm đi — và núm nào cũng có thể tự động hóa.","featuresPage.cards.daw.title":"Trong mọi DAW","featuresPage.cards.daw.body":"CLAP và VST3 trên Windows, macOS và Linux, AU trên macOS, cùng một ứng dụng độc lập. Được lưu cùng dự án, báo độ trễ để DAW căn chỉnh mọi thứ, và an toàn khi chạy nhiều phiên bản cùng lúc.","featuresPage.cards.offline.title":"Ngoại tuyến, riêng tư, không dùng AI","featuresPage.cards.offline.body":"Không tài khoản, không đo lường từ xa và không mô hình. Plugin và ứng dụng không bao giờ kết nối mạng; việc kiểm tra cập nhật và kích hoạt giấy phép chạy trong một trình trợ giúp riêng, chỉ khi bạn yêu cầu.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng. Đây là chính chiếc thang mà kế hoạch nội bộ đang theo — nếu một bên di chuyển, bên kia cũng di chuyển, và một cổng kiểm tra khi dựng sẽ đối chiếu chúng.","ladder.rung.v0.1.0":"Nền móng: plugin tải được dưới dạng CLAP, VST3 và AU lẫn ứng dụng độc lập, cho âm thanh của bạn đi qua nguyên vẹn, đề nghị bạn chấp nhận giấy phép, và mọi cổng kiểm tra chất lượng đều chạy.","ladder.rung.v0.2.0":"Joint: một rack cho cả chuỗi vocal, những mô-đun EQ, dynamics và màu âm đầu tiên trên phần cứng được render, cùng đèn thu âm.","ladder.rung.v0.3.0":"Không gian: delay, reverb, doubling, độ rộng và bốn kênh return hiệu ứng, khớp nhịp với dự án của bạn.","ladder.rung.v0.4.0":"Chỉnh cao độ: chỉnh cao độ bằng xử lý tín hiệu cổ điển, giọng (key) tìm từ vocal của bạn và một chế độ độ trễ thấp để thu âm.","ladder.rung.v0.5.0":"Ánh sáng đầu tiên: tìm một nghệ sĩ và thời kỳ, và cả chuỗi nạp chỉ với một cú nhấp. Phiên bản hoàn chỉnh đầu tiên.","ladder.rung.v0.5.5":"Input Check, chuỗi cho ad-lib, preset của riêng bạn và hoàn tác.","ladder.rung.v0.5.6":"Thẻ trực quan: mỗi mô-đun cho thấy nó làm gì — đường cong EQ trên phổ trực tiếp của giọng hát bạn, đường cong bộ nén cùng mức nó giảm đi — chứ không chỉ có núm.","ladder.rung.v0.6.0":"Đợt chuỗi nghệ sĩ đầu tiên, một chuỗi cho mỗi thể loại và trang danh mục.","ladder.rung.v0.7.0":"Trong mọi DAW: lưu cùng dự án, tự động hóa được, báo độ trễ và an toàn khi chạy nhiều phiên bản cùng lúc.","ladder.rung.v0.8.0":"Ứng dụng độc lập với đầy đủ sức mạnh, và Takelight trên macOS và Linux.","ladder.rung.v0.9.0":"Đợt chuỗi nghệ sĩ thứ hai, cùng một lượt rà soát độ chân thực và hiệu năng.","ladder.rung.v0.9.5":"Reference Match: tải một bản tham chiếu, và Takelight đọc các độ trễ, vang, âm sắc và mọi thứ còn lại trong giọng hát của nó, rồi đề xuất chúng trên chính các mô-đun của mình.","ladder.rung.v1.0.0-beta":"Gia cố: trình cài đặt cho ba hệ điều hành, kiểm tra cập nhật, bản dùng thử và giấy phép, cùng sổ tay đầy đủ. Vẫn chưa có lượt tải xuống nào trên trang này.","ladder.rung.v1.0.0-rc":"Bản ứng viên phát hành: mọi tệp đều được rà soát và mọi host đều được thử thủ công.","ladder.rung.v1.0.0":"Bản phát hành: bản dùng thử miễn phí, giấy phép trả một lần và những lượt tải xuống đầu tiên mà trang này từng cung cấp.","ladder.rung.v1.1.0":"Vocal Match: âm sắc giọng hát của bạn được chỉnh theo một bản tham chiếu thuộc về bạn.","ladder.rung.v1.2.0":"Bè double và hòa âm, được xếp chồng sẵn cho bạn.","ladder.rung.v1.3.0":"Đợt chuỗi nghệ sĩ thứ ba, và các chuỗi do nhà sản xuất gửi đến.","ladder.rung.v1.4.0":"Cầu nối tới Freally MIDI Master và Freally Unloop.","ladder.rung.v1.5.0":"Pro Tools dưới dạng plugin (AAX), nếu điều khoản của Avid cho phép.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có, và sẽ không có cho đến 1.0.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.voice.title":"Một chuỗi không phải là một giọng hát","honest.voice.body":"Một chuỗi tái tạo cách xử lý: tuning, EQ, nén, delay và reverb. Giọng của bạn, micro của bạn, phòng thu của bạn và cách hát của bạn vẫn là của bạn, và không preset nào làm ai nghe giống người khác.","honest.start.title":"Một chuỗi là điểm khởi đầu","honest.start.body":"Một chuỗi là nơi giọng hát của bạn bắt đầu, không phải lời hứa về một âm thanh. Vặn các macro, mở rack và biến nó thành của bạn; mọi thay đổi của bạn không bao giờ bị khóa.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Không có bản beta trên trang này, không có bản xem trước, không có quyền truy cập sớm. Phiên bản 1.0 đi kèm bản dùng thử miễn phí toàn bộ plugin và một giấy phép trả một lần.","honest.network.title":"Nó không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập không chứa chút mã mạng nào, và một cổng kiểm tra bản dựng sẽ thất bại nếu có mã được thêm vào. Việc kiểm tra cập nhật và kích hoạt giấy phép sẽ nằm trong một trình trợ giúp riêng chỉ hoạt động khi bạn yêu cầu.","site.tagline":"Chuỗi vocal của mọi thời kỳ. Một plugin.","footer.licence":"Phần mềm độc quyền — bảo lưu mọi quyền. © Mike Weaver. Không phải mã nguồn mở. Liên hệ: freallyproducts@gmail.com.","footer.yours":"Âm thanh, preset và dự án bạn làm với Freally Takelight là của bạn.","footer.disclaimer":"Tên nghệ sĩ chỉ dùng để chỉ một phong cách. Freally Takelight không liên kết với, không được ủng hộ hay chấp thuận bởi bất kỳ nghệ sĩ, nhà sản xuất, kỹ sư, hãng đĩa, ấn phẩm hay nhà làm plugin nào. Một chuỗi áp dụng xử lý, không phải giọng hát.","featuresPage.lead":"Một plugin vocal với trọn một chuỗi vocal cho mỗi nghệ sĩ và mỗi thời kỳ — chỉnh cao độ, EQ, nén, khử xì, delay, reverb và bus vocal — dựng từ chính các mô-đun của nó.","featuresPage.version":"Trang này mô tả Freally Takelight phiên bản 1.0: mọi thứ trên đây đều có trong 1.0, và không có gì được lên kế hoạch sau 1.0 xuất hiện ở đây.","featuresPage.numbers.plugin":"plugin cho cả chuỗi, không cần mua thêm plugin nào khác","featuresPage.numbers.macros":"macro: Chỉnh cao độ, Âm sắc, Không gian và Mức độ","featuresPage.numbers.returns":"kênh return hiệu ứng, cùng một bus vocal","featuresPage.numbers.plugins":"định dạng plugin, cùng một ứng dụng độc lập","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.borrowed":"impulse response, sample hay preset sao chép","featuresPage.free.title":"Chưa có gì để mua","featuresPage.free.body":"Trước phiên bản 1.0, không có gì để bán và không có gì để tải xuống. Sau đó sẽ có bản dùng thử miễn phí toàn bộ plugin và một mức giá duy nhất, trả một lần: không thuê bao và không tài khoản. Âm thanh bạn làm ra với nó là của bạn.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.tune.title":"Chỉnh cao độ và Auto Key","featuresPage.cards.tune.body":"Chỉnh cao độ bằng xử lý tín hiệu cổ điển, với giọng (key) được tìm từ vocal của bạn hoặc từ sidechain, và một chế độ độ trễ thấp để thu âm qua nó.","featuresPage.cards.inputCheck.title":"Input Check và A/B","featuresPage.cards.inputCheck.body":"Input Check nghe mười giây của lần thu và đặt Núm Đầu vào, cùng gate, thông cao và bộ khử âm xì mà chuỗi của bạn có. A/B so sánh chuỗi với một tệp tham chiếu bạn nạp, đã cân bằng độ to, hoặc với một phiên bản thứ hai của chính nó; tệp tham chiếu không bao giờ được lưu.","featuresPage.cards.lightDark.title":"Sáng và tối","featuresPage.cards.lightDark.body":"Một chế độ tối và một chế độ sáng, đều mang màu xanh Freally, với mọi núm, fader và công tắc được render trong Blender cho từng chế độ, cùng đèn thu âm sáng lên khi chuỗi đang hoạt động.","featuresPage.compare.title":"Đặt cạnh các công cụ thương mại","featuresPage.compare.intro":"Freally Takelight 1.0 đặt cạnh những plugin vocal mà producer tìm đến khi muốn một âm thanh có tên. Mỗi ô của sản phẩm khác lấy từ trang của nhà sản xuất hoặc từ các bài viết đã đăng, kiểm tra vào tháng 10 năm 2026; ô nào chúng không làm rõ được thì ghi là chưa xác minh.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.ourPrice":"Một mức giá, trả một lần, sau bản dùng thử miễn phí","featuresPage.compare.note.muzePrice":"trọn đời, hoặc $24 mỗi 4 tuần","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.row.artists":"Chuỗi đặt theo tên nghệ sĩ","featuresPage.compare.legend.yes":"có","featuresPage.compare.note.artistEra":"theo nghệ sĩ, thời kỳ và vai trò","featuresPage.compare.note.muzePresets":"52 preset nghệ sĩ","featuresPage.compare.legend.no":"không","featuresPage.compare.note.engineerChain":"chuỗi của một kỹ sư","featuresPage.compare.note.producerChain":"chuỗi của một nhà sản xuất","featuresPage.compare.row.modes":"Chế độ đơn giản và nâng cao","featuresPage.compare.row.key":"Tìm giọng (key) từ vocal của bạn","featuresPage.compare.row.formats":"CLAP, VST3 và AU","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.row.systems":"Windows, macOS và Linux","featuresPage.compare.row.noAi":"Không dùng AI hay học máy","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Chỉ Takelight có chuỗi theo nghệ sĩ, thời kỳ và vai trò, cả ba định dạng plugin, Linux bên cạnh Windows và macOS, và hoàn toàn không có AI.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Muze hiện có 52 preset nghệ sĩ và chạy trong Pro Tools; những chuỗi nghệ sĩ đầu tiên của Takelight đã đến cùng phiên bản 0.5.0, và ở bản 1.0 nó không phải plugin cho Pro Tools. CLA Vocals và The Spirit được làm cùng chính kỹ sư và nhà sản xuất mang tên chúng.","featuresPage.compare.asOf":"Cột của Takelight là phiên bản 1.0, vẫn chưa ra mắt. Các sản phẩm khác cũng thay đổi; bảng này tính đến tháng 10 năm 2026. Tên sản phẩm thuộc về chủ sở hữu và ở đây chỉ dùng để so sánh.","featuresPage.why.title":"Vì sao nó được làm như vậy","featuresPage.why.built.title":"Tự xây, không vay mượn","featuresPage.why.built.body":"Mỗi mô-đun là xử lý tín hiệu cổ điển của riêng Takelight. Không impulse response, không sample, không mã vay mượn và không thiết lập nào sao chép từ preset của sản phẩm khác.","featuresPage.why.names.title":"Tên gọi trung thực","featuresPage.why.names.body":"Một chuỗi được đặt tên theo nghệ sĩ và thời kỳ, không hơn. Không hình ảnh, không ảnh bìa và không hứa hẹn làm ai đó nghe giống người khác.","featuresPage.why.reference.title":"Bản tham chiếu của bạn, cùng mức","featuresPage.why.reference.body":"A/B đặt một tệp tham chiếu bạn nạp bên cạnh giọng hát của bạn ở cùng độ to, để bản to hơn không bao giờ đánh lừa tai bạn. Bản tham chiếu chỉ nằm trong bộ nhớ và không bao giờ được lưu.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không đo lường từ xa và không đám mây. Giọng hát của bạn không bao giờ rời khỏi máy, và một cổng kiểm tra bản dựng sẽ thất bại nếu mã mạng từng được thêm vào plugin hay ứng dụng.","featuresPage.why.roster.title":"Một danh mục cho cả gia đình","featuresPage.why.roster.body":"Nghệ sĩ và thể loại dùng chung tên với Freally MIDI Master và Freally Unloop, nên một danh mục duy nhất chạy suốt dòng Freally.","featuresPage.coming.title":"Những gì vẫn đang đến","featuresPage.coming.intro":"Nói thẳng, vì một danh sách tính năng giấu đi những chỗ trống thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Takelight được xây từng nấc một: chưa phải mọi thứ trên đó đều đã xong. Mỗi nấc trên đường tới 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.voice":"Nó không thay đổi người đang hát, và không bao giờ bắt chước một giọng hát.","featuresPage.limits.roster":"Nó chưa có mọi nghệ sĩ. Danh mục lớn dần theo từng phiên bản.","featuresPage.limits.match":"Nó không tự động khớp vocal của bạn với một bản tham chiếu; Vocal Match được lên kế hoạch sau 1.0.","featuresPage.limits.aax":"Ở bản 1.0, nó không phải plugin cho Pro Tools (AAX).","featuresPage.coming.downloads":"Không có bản tải xuống nào trước phiên bản 1.0, và cũng không có trên trang này.","docs.intro":"Sách hướng dẫn này lớn dần theo từng phiên bản. Hiện nó nói về cách tìm một chuỗi, preset của bạn, chế độ Đơn giản và bốn núm của nó, A/B, rack và những gì mỗi thẻ hiển thị, hoàn tác, bốn kênh trả về hiệu ứng, Chỉnh cao độ, Input Check và ba mươi mô-đun của nó.","docs.start.title":"Bắt đầu","docs.browser.title":"Tìm một chuỗi","docs.presets.title":"Preset của bạn","docs.simple.title":"Chế độ Đơn giản và bốn núm","docs.ab.title":"A/B","docs.rack.title":"Rack","docs.cards.title":"Mỗi thẻ hiển thị gì","docs.undo.title":"Hoàn tác và làm lại","docs.returns.title":"Kênh trả về và ném","docs.tune.title":"Chỉnh cao độ và Auto Key","docs.inputCheck.title":"Input Check","docs.automation.title":"Tự động hóa","docs.lamp.title":"Đèn thu âm và đồng hồ đo","docs.modules.title":"Các mô-đun","docs.project.title":"Được lưu cùng dự án","docs.agreement.title":"Thỏa thuận cấp phép","docs.settings.title":"Cài đặt","docs.language.title":"Ngôn ngữ","docs.disclaimer.title":"Tuyên bố miễn trừ","docs.privacy.title":"Quyền riêng tư và mạng","docs.report.title":"Khi có sự cố","docs.start.p1":"Takelight chạy trong DAW của bạn dưới dạng plugin CLAP, VST3 hoặc AU, hoặc tự chạy như một ứng dụng độc lập. Hãy đặt nó lên một track vocal. Nó mở ở chế độ Đơn giản: tìm một nghệ sĩ hoặc một thể loại, chọn một thời kỳ và một vai trò, và cả chuỗi sẽ được nạp. Cho đến khi bạn nạp một chuỗi hoặc thêm một mô-đun, âm thanh của bạn đi qua nguyên vẹn.","docs.start.p2":"Không có bản tải xuống nào trước phiên bản 1.0.0, và phần mã được giữ riêng tư.","docs.browser.p1":"Gõ vào ô tìm kiếm ở trên cùng — tên nghệ sĩ, biệt danh hoặc thể loại — hoặc nhấn Ctrl+K (Cmd+K trên Mac) từ bất cứ đâu. Các chuỗi hiện ra ngay khi bạn gõ: mỗi nghệ sĩ với các thời kỳ của mình, mỗi thời kỳ với các năm và các vai trò của nó, như Giọng chính, Ad-lib hoặc FX. Chọn một mục và cả chuỗi sẽ được nạp theo thứ tự, không có tiếng tách, trong khi bài đang chạy. Các phím mũi tên di chuyển trong danh sách, Enter để nạp, và Escape để đóng danh sách.","docs.browser.p2":"Khi ô tìm kiếm trống, nó gợi ý các chuỗi bạn nạp gần đây nhất. Với một nghệ sĩ chưa có chuỗi, nó gợi ý các chuỗi thuộc thể loại của nghệ sĩ đó, còn với một cái tên nó không biết, nó sẽ nói rõ và gợi ý một thể loại.","docs.browser.p3":"Phiên bản 0.6.0 có Drake ở ba thời kỳ — So Far Gone (2009), Take Care (2011) và thời hiện đại (2016–2026) — cùng một chuỗi FX từ thời Take Care; thêm bốn mươi nghệ sĩ, theo từng thời kỳ; và một chuỗi Giọng chính cùng một chuỗi Ad-lib cho mỗi thể loại trong 73 thể loại, trap ở hai thập niên. Trang Danh mục phong cách liệt kê tất cả. Mỗi chuỗi được đặt tên theo nghệ sĩ hoặc thể loại và thời kỳ của nó, và chỉ vậy thôi.","docs.presets.p1":"Lưu preset… ở trên cùng giữ chuỗi đúng như bạn đã định hình nó — mọi mô-đun, núm, mức gửi và fader, cùng bốn núm của chế độ Đơn giản — dưới một cái tên bạn chọn. Mỗi preset là một tệp trong Tài liệu › Freally Takelight › Presets, nên bạn có thể sao lưu hoặc gửi nó cho ai đó.","docs.presets.p2":"Preset của tôi… liệt kê chúng, mỗi preset kèm chuỗi mà nó dựa trên, để tải, đổi tên, xuất hoặc xóa. Nhập… đưa vào một preset ai đó gửi cho bạn, và đánh số tên của nó nếu bạn đã có một preset cùng tên. Tệp không phải preset của Takelight, lớn hơn 256 KB hoặc được lưu bởi một phiên bản mới hơn sẽ bị từ chối, và danh sách cho biết lý do.","docs.presets.p3":"Preset của bạn cũng có trong ô tìm kiếm, dưới mục Preset của tôi. Khi chuỗi mà một preset dựa trên được cập nhật trong một phiên bản sau, preset sẽ được tải lên chuỗi đã cập nhật, giữ mọi thay đổi bạn đã làm, và báo cho bạn biết.","docs.simple.p1":"Đơn giản hiển thị đèn thu âm, tên chuỗi, bốn núm lớn và đồng hồ Vào và Ra; Nâng cao, bật từ công tắc ở trên cùng, hiển thị toàn bộ rack. Dự án của bạn nhớ bạn đã để nó ở chế độ xem nào, và Cài đặt cho bạn chọn phiên bản mới sẽ mở ở chế độ nào.","docs.simple.p2":"Chỉnh cao độ quyết định giọng hát được chỉnh nhanh đến đâu và tự nhiên đến đâu. Âm sắc làm chuỗi tối hơn hoặc sáng hơn, quanh 1 kHz, và bộ khử âm xì đi theo. Không gian tăng hoặc giảm mọi kênh gửi hiệu ứng cùng lúc, tối đa 12 dB. Mức độ đặt cả chuỗi so với giọng hát khô của bạn, từ khô hoàn toàn ở 0 % đến toàn bộ chuỗi ở 100 %.","docs.simple.p3":"Khi Chỉnh cao độ, Âm sắc và Không gian ở giữa và Mức độ ở 100 %, chuỗi chạy như cách nó được tạo ra, và mọi chuỗi đều được nạp như vậy. Mỗi núm là một tham số host, nên DAW của bạn có thể tự động hóa nó, và nhấp đúp sẽ đưa nó về chỗ cũ.","docs.ab.p1":"Tải bản tham chiếu… mở hộp thoại chọn tệp của hệ thống, hoặc bạn có thể thả một tệp lên cửa sổ. Nó đọc WAV, AIFF, FLAC và MP3, dài tối đa 20 phút, và thanh hiển thị tên tệp, độ dài và độ to của nó. B phát bản tham chiếu từ vị trí hiện tại của DAW (từ đầu trong ứng dụng độc lập), A là chuỗi của bạn, và mỗi lần chuyển là một lần chuyển tiếp mượt mà dài 20 mili giây.","docs.ab.p2":"Cân bằng độ to phát bản tham chiếu ở độ to của giọng hát bạn, để bạn đánh giá âm sắc chứ không phải mức âm lượng. Bản tham chiếu chỉ được giữ trong bộ nhớ: nó không bao giờ được lưu cùng dự án, một preset hay bất cứ đâu khác, và tệp trên ổ đĩa mạng sẽ bị từ chối.","docs.ab.p3":"So sánh các chuỗi giữ hai phiên bản của chuỗi của bạn. A là phiên bản bạn đang chỉnh; nhấn B và nó bắt đầu là một bản sao, nên không có gì thay đổi; chỉnh nó, và A và B mỗi bên giữ cài đặt riêng. Cả hai đều được lưu cùng dự án.","docs.rack.p1":"Rack chứa toàn bộ chuỗi theo thứ tự tín hiệu, trong bốn hàng: Tầng đầu (khe F1 và F2), Insert (I1 đến I12), bốn Kênh trả về hiệu ứng (A đến D, khe R1 đến R12) và Bus (B1 đến B4).","docs.rack.p2":"Chọn một mô-đun từ menu của một khe trống để thêm nó. Thẻ của nó hiển thị mọi điều khiển nó có: núm cho giá trị, công tắc, và menu cho các tùy chọn. Phần đầu thẻ chứa đặc tính của nó (khi có nhiều hơn một), Bỏ qua (B), Solo (S) và dấu × để gỡ nó ra.","docs.rack.p3":"Mọi thay đổi đều không có tiếng tách. Một mô-đun bạn thêm vào hay gỡ ra sẽ mờ dần vào hoặc ra, một đặc tính mới được chuyển tiếp mượt mà, và mọi núm đều lướt nhẹ, nên bạn có thể làm việc trong khi bài đang chạy. Một mô-đun bị bỏ qua vẫn giữ độ trễ của nó, nên DAW của bạn luôn khớp thời gian.","docs.rack.p4":"Mọi điều khiển đều dùng được từ bàn phím. Tab di chuyển giữa chúng; các phím mũi tên vặn núm, và Shift vặn theo bước lớn hơn; Home và End đưa núm về hai đầu; nhấp đúp đưa nó về mặc định.","docs.rack.p5":"Một rack chứa được số núm bằng số núm Takelight có thể điều khiển cùng lúc — lấp mọi khe bằng những mô-đun lớn nhất sẽ vượt quá con số đó — nên quá giới hạn ấy, mô-đun sẽ bị từ chối và rack báo rằng nó đã đầy.","docs.cards.p1":"Bên cạnh các núm, thẻ của mỗi mô-đun vẽ ra việc mô-đun đó làm, được tính từ chính phần toán học tạo nên âm thanh. Các EQ — EQ tham số, EQ bàn mixer và EQ chương trình — vẽ đường cong của chúng trên giọng hát của bạn khi nó phát: phổ trước EQ thì mờ, sau EQ thì sáng, với các đỉnh được giữ lại trong chốc lát. Mỗi băng tần có một chấm trên đường cong: kéo nó để dời tần số và độ lợi của băng tần cùng lúc, lăn bánh xe chuột trên nó để chỉnh độ rộng, nhấp đúp vào nó để đưa băng tần về như cũ, hoặc dùng các phím mũi tên. Cả một lần kéo là một bước hoàn tác. Bộ khử âm xì vẽ băng tần mà nó lắng nghe và mức cắt mà nó tạo ra, còn Trim vẽ bộ lọc thông cao của nó.","docs.cards.p2":"Các bộ nén, Bộ cân mức tự động và Bộ giới hạn vẽ đường cong của chúng — mức đầu vào so với mức đầu ra — với một chấm ở vị trí giọng hát của bạn đang nằm trên đó lúc này, và bên dưới là mức giảm độ lợi của bốn giây gần nhất. Một nốt đều giữ chấm nằm trên đường cong; một khởi âm gắt có thể đẩy nó lên phía trên trong chốc lát, trước khi bộ nén bắt kịp. Kéo ngưỡng dọc theo đường cong, hoặc dùng các phím mũi tên: thao tác này vặn núm đặt ngưỡng đó. Thẻ của Gate cho thấy mức nó nghe được so với ngưỡng của nó, được tô bóng ở những chỗ nó đóng.","docs.cards.p3":"Độ trễ vẽ các lần lặp của nó trên một dòng thời gian theo phách và ô nhịp của dự án, mỗi lần lặp to đúng bằng mức phản hồi và bộ lọc để lại; ở Qua lại, các lần lặp bên trái nằm trên đường kẻ và các lần lặp bên phải nằm dưới. Vang vẽ độ tắt của nó — trễ trước, các phản xạ sớm và đuôi vang — còn Cổng đảo ngược vẽ độ dâng của nó. Bộ nhân đôi, Hợp xướng và Độ rộng hiển thị trường stereo nhìn từ trên xuống, còn Bão hòa, Bộ kích âm và Âm thanh lo-fi hiển thị đường cong của chúng và các hài âm mà đường cong đó thêm vào giọng hát của bạn như nó đang có lúc này.","docs.cards.p4":"Chỉ những thẻ đang hiện trên màn hình mới vẽ, và tối đa tám thẻ EQ hiển thị phổ giọng hát của bạn cùng lúc. Chỉnh cao độ thay vào đó có biểu đồ cao độ của nó, còn Dịch cao độ chỉ có các núm.","docs.undo.p1":"Các mũi tên ở trên cùng hoàn tác và làm lại mọi thay đổi đối với âm thanh, tối đa 100 bước: một núm (cả một lần kéo là một bước), một mô-đun được thêm hoặc gỡ ra, đặc tính của nó, Bỏ qua và Solo, các mức gửi và fader, bốn núm của chế độ Đơn giản, Núm Đầu vào, một chuỗi hoặc preset được tải, và lần Áp dụng của Input Check. Ctrl+Z để hoàn tác, Ctrl+Shift+Z hoặc Ctrl+Y để làm lại (⌘Z và ⌘⇧Z trên Mac), khi cửa sổ của Takelight đang có tiêu điểm, nên DAW của bạn vẫn giữ phím tắt riêng.","docs.undo.p2":"Chế độ xem, chủ đề, ngôn ngữ và bản tham chiếu A/B không bao giờ bị hoàn tác, và tự động hóa trong DAW của bạn cũng vậy. Mỗi dự án bắt đầu với một lịch sử mới khi được mở, và mỗi phía của phần so sánh cũng vậy khi bạn chuyển sang nó.","docs.returns.p1":"Mỗi kênh trong bốn kênh trả về, A đến D, được cấp tín hiệu từ cuối hàng Insert qua núm Gửi của nó, từ tắt đến +6 dB. Giọng hát đi qua ba khe của kênh trả về — chẳng hạn một Độ trễ và một Vang — và fader của kênh trả về quyết định bao nhiêu phần trong đó hòa vào giọng hát khô trên đường đi vào Bus.","docs.returns.p2":"Giữ phím Ném của một kênh trả về và giọng hát được ném vào đó: mức gửi của nó tăng lên 0 dB, rồi hạ xuống khi bạn thả ra, trong 5 mili giây cho mỗi chiều. Ném A đến D cũng là tham số host, nên DAW của bạn có thể ghi lại một lần ném và phát lại — một đuôi lặp của Độ trễ trên đúng một từ.","docs.returns.p3":"Một Độ trễ đặt theo giá trị nốt sẽ khớp nhịp với tempo dự án của bạn, và đi theo khi tempo thay đổi giữa bài.","docs.tune.p1":"Chỉnh cao độ kéo từng nốt được hát về nốt gần nhất trong tông của nó. Tốc độ chỉnh quyết định nhanh đến đâu: ở 0 ms giọng nhảy từ nốt này sang nốt khác, kiểu âm thanh cứng, bậc thang; chậm hơn thì giọng trượt tới đó, và ở vài trăm mili giây thì gần như không nghe ra việc chỉnh. Tự nhiên hóa để các nốt dài ổn định chậm hơn, còn Linh hoạt giữ lại những đoạn luyến và vibrato đi xa nốt nhất. Formant của giọng vẫn ở nguyên chỗ, nên giọng giữ được chất riêng, còn hơi thở và phụ âm đi qua nguyên vẹn.","docs.tune.p2":"Menu Tông bắt đầu ở Auto Key: Chỉnh cao độ nghe giọng hát của bạn và chốt tông của nó sau khoảng bốn giây hát; cho đến lúc đó nó chỉnh về nửa cung gần nhất, trong khi đèn thu âm sáng màu hổ phách. Thẻ cho biết tông nó nghe được, và Khóa giữ tông đó. Hoặc tự chọn Crômatic hay bất kỳ tông nào trong 24 tông. Nếu sau 20 giây hát mà vẫn chưa nghe ra tông nào, thẻ sẽ nhờ bạn chọn một tông.","docs.tune.p3":"Đồ thị cao độ hiển thị bốn giây gần nhất: cao độ bạn hát là một đường mảnh và cao độ mà Chỉnh cao độ gửi đi là một đường xanh lục, phía trên một đường cho nốt mà nó đang kéo về.","docs.tune.p4":"Để nghe một nốt trước khi chỉnh, Chỉnh cao độ chờ 21 mili giây, và Takelight báo điều đó cho DAW của bạn, nên giọng hát vẫn khớp nhịp với beat. Khi bạn thu âm, khoảng chờ ấy sẽ lọt vào tai nghe, vì vậy tham số host Tracking, ở chế độ Auto, hạ Chỉnh cao độ xuống 4 mili giây mỗi khi DAW của bạn thu âm, và thẻ sẽ báo như vậy. Đặt Tracking ở On hoặc Off để tự chọn.","docs.tune.p5":"Mỗi rack chứa một Chỉnh cao độ, vì một Chỉnh cao độ chỉnh cho cả giọng hát.","docs.tune.p6":"Auto Key cũng có thể tìm tông từ beat. Hãy gửi beat vào đầu vào sidechain của Takelight trong DAW và đặt Lắng nghe, trên thẻ của Chỉnh cao độ, thành Sidechain: Chỉnh cao độ sẽ theo các hợp âm của beat. Dự án của bạn nhớ lựa chọn này, còn Cài đặt đặt nó cho các dự án mới. Khi không có gì phát trên sidechain, Chỉnh cao độ nghe giọng hát của bạn, và thẻ sẽ cho biết điều đó.","docs.inputCheck.p1":"Input Check, ở phía trên rack, giúp bạn chuẩn bị trước khi thu. Hãy nhấn nó rồi hát hoặc chơi phần sẽ thu trong mười giây; đèn thu âm sáng màu hổ phách trong lúc nó nghe. Nó cần ít nhất hai giây giọng, và sẽ hỏi lại nếu nghe được quá ít.","docs.inputCheck.p2":"Sau đó nó hiển thị những gì nghe thấy — đỉnh, mức, độ to, mức nhiễu nền, tiếng ù dưới 80 Hz, âm xì và tiếng bật hơi — và những gì đề xuất: Núm Đầu vào, để đưa giọng bạn về một mức phù hợp, cùng ngưỡng gate, thông cao và ngưỡng khử âm xì. Nó chỉ đặt các mô-đun mà chuỗi của bạn đã có; mô-đun nào thiếu sẽ ghi Không có trong chuỗi này, và không có gì được thêm vào thay bạn.","docs.inputCheck.p3":"Không có gì thay đổi cho đến khi bạn nhấn Áp dụng, và Hoàn tác rút lại toàn bộ lần Áp dụng chỉ trong một bước. Loại bỏ giữ mọi thứ như cũ. Nếu phần thu bị clip, nó sẽ nhờ bạn giảm độ lợi trên sound card, vì tín hiệu đã bị clip thì không sửa được sau khi thu.","docs.automation.p1":"Mỗi khe sở hữu 24 tham số host, được đặt tên theo khe (F1 đến B4), và các núm cùng công tắc của một mô-đun nhận chúng theo thứ tự, nên DAW của bạn có thể tự động hóa chúng. Danh sách tham số không bao giờ thay đổi khi bạn thêm, đổi hay gỡ một mô-đun.","docs.automation.p2":"Một vài thiết lập không được tự động hóa, vì thay đổi chúng giữa chừng một nốt sẽ gây tiếng tách: loại và độ dốc của một băng tần EQ, độ dốc của một bộ lọc, và các chế độ như phát hiện của bộ khử âm xì. Dù vậy, chúng vẫn được lưu cùng dự án của bạn.","docs.lamp.p1":"Đèn thu âm ở phía trên rack sáng xanh lục khi có mô-đun trong rack và giọng của bạn đang vào, nháy đỏ khi tín hiệu vào bị clip, và tắt trong mọi trường hợp khác. Nó chuyển sang màu hổ phách khi Auto Key của Chỉnh cao độ đang nghe để tìm tông, và khi Input Check đang nghe.","docs.lamp.p2":"Đồng hồ Vào và Ra ở hai bên hiển thị kênh trái và phải, và bên cạnh đồng hồ Vào, Núm Đầu vào đặt mức tín hiệu đi vào, từ −24 đến +24 dB; DAW của bạn có thể tự động hóa nó. Mỗi đồng hồ có một đèn clip sáng cho đến khi bạn nhấp vào nó. Thẻ của một bộ nén cho thấy nó đang giảm giọng hát bao nhiêu, ngay trong lúc giảm.","docs.modules.p1":"Phiên bản 0.6.0 có ba mươi mô-đun. Mỗi mô-đun là thiết kế riêng của Takelight, và không mô-đun nào tự nhận là sản phẩm khác.","docs.modules.tune.title":"Chỉnh cao độ","docs.modules.tune.p1":"Chỉnh cao độ theo một tông — Auto Key, Crômatic hoặc một trong 24 tông — với Tốc độ chỉnh từ 0 đến 400 ms, Tự nhiên hóa và Linh hoạt, cùng một đồ thị cao độ khi hát và sau khi chỉnh. Mỗi rack một bộ; xem Chỉnh cao độ và Auto Key ở trên.","docs.modules.trim.title":"Trim","docs.modules.trim.p1":"Độ lợi, cực tính và bộ lọc thông cao với độ dốc tùy chọn: thứ đầu tiên trong hầu hết các chuỗi.","docs.modules.parametric.title":"EQ tham số","docs.modules.parametric.p1":"Tám băng tần, mỗi băng là chuông, kệ, cắt hoặc notch, với độ dốc cắt từ 6 đến 96 dB mỗi quãng tám. Các núm của nó hiển thị từng băng tần một — hãy chọn băng tần theo số của nó — và mỗi băng tần có chấm riêng trên đường cong.","docs.modules.console.title":"EQ bàn mixer","docs.modules.console.p1":"EQ kênh của một bàn mixer: bộ lọc thông cao và thông thấp cùng bốn băng tần, với bốn đặc tính — Kiểu Anh E, Kiểu Anh G, Lớp A và Q tỉ lệ.","docs.modules.program.title":"EQ chương trình","docs.modules.program.p1":"Tăng và cắt rộng, nhẹ nhàng ở vùng trầm và vùng cao, cùng một tầng đèn để thêm độ ấm.","docs.modules.dynamiceq.title":"EQ động","docs.modules.dynamiceq.p1":"Hai dải, mỗi dải là chuông hoặc kệ, có độ lợi thay đổi theo mức âm trong phần giọng của riêng nó: dải âm cắt một vùng chói hoặc ù chỉ khi nó to lên, dải dương nâng vùng đó lên khi giọng mạnh dần. Mỗi dải có tần số, Q, ngưỡng, tỉ lệ và phạm vi, cùng một attack, release và đầu ra chung.","docs.modules.opto.title":"Bộ nén quang","docs.modules.opto.p1":"San mức mượt mà theo sát màn trình diễn, chỉ từ một núm Giảm đỉnh, với đặc tính Quang và Quang đèn, ở chế độ nén hoặc giới hạn.","docs.modules.fet.title":"Bộ nén FET","docs.modules.fet.p1":"Nhanh và nổi bật, với các tỉ số nén cố định và thiết lập Tất cả cho kiểu nén mạnh bạo, cùng điều khiển Mix cho nén song song.","docs.modules.vca.title":"Bộ nén VCA","docs.modules.vca.p1":"Sạch và chính xác, với đặc tính Bus và Kênh, phát hiện RMS hoặc đỉnh, thông cao sidechain và một điều khiển Mix.","docs.modules.multiband.title":"Bộ nén đa dải","docs.modules.multiband.p1":"Chia giọng thành dải trầm, trung và cao tại hai điểm cắt rồi nén từng dải riêng, với ngưỡng, tỉ lệ và độ lợi cho mỗi dải cùng attack, release, knee, đầu ra và trộn chung. Khi không bớt gì, các dải cộng lại thành giọng như ban đầu.","docs.modules.varimu.title":"Bộ nén vari-mu","docs.modules.varimu.p1":"Một bộ nén đèn có tỉ lệ tăng lên khi nó làm việc càng mạnh, nên nó bắt đầu nhẹ nhàng và giữ chắc, với sáu hằng số thời gian; 5 và 6 nhả càng chậm khi nó đã nén càng lâu.","docs.modules.punch.title":"Bộ nén Punch","docs.modules.punch.p1":"Một bộ nén giàu cá tính với năm đặc tính, từ Bình thường đến Méo tiếng 3, có Nuke cho kiểu nén cực mạnh và một điều khiển Mix.","docs.modules.vox.title":"Bộ ổn định mức giọng","docs.modules.vox.p1":"Làm đều mức giọng hát chỉ với một ngưỡng và một đầu ra.","docs.modules.rider.title":"Bộ cân mức tự động","docs.modules.rider.p1":"Điều chỉnh mức giọng hát hướng về một độ to mục tiêu — nâng những từ nhỏ, hạ những từ lớn — trong phạm vi và với tốc độ do bạn đặt, và để yên những hơi thở giữa các câu hát. Tùy chọn nhìn trước 10 ms cho phép nó điều chỉnh ngay trước một từ; nó thêm 10 ms độ trễ, và Takelight báo độ trễ này cho DAW của bạn.","docs.modules.deesser.title":"Bộ khử âm xì","docs.modules.deesser.p1":"Chế ngự những âm \"s\" chói gắt, tách dải hoặc toàn dải, với dạng chuông hoặc kệ, và phát hiện tương đối hoặc tuyệt đối.","docs.modules.gate.title":"Gate","docs.modules.gate.p1":"Một gate hoặc một expander giữa các câu hát, với giữ, hysteresis và bộ lọc sidechain để tiếng thở và âm lọt vào không mở nó.","docs.modules.saturation.title":"Bão hòa","docs.modules.saturation.p1":"Băng từ, Đèn, Biến áp, Thổi phồng và Cắt đỉnh, được oversample để các họa âm nó thêm vào luôn sạch; Cắt đỉnh giữ các đỉnh ở toàn thang qua một knee ngắn và mượt.","docs.modules.exciter.title":"Bộ kích âm","docs.modules.exciter.p1":"Thêm họa âm phía trên một tần số do bạn chọn — lẻ, chẵn hoặc pha trộn cả hai — để tăng độ hiện diện và độ thoáng. Chỉ các họa âm được thêm vào; bản thân giọng hát đi qua nguyên vẹn.","docs.modules.lofi.title":"Âm thanh lo-fi","docs.modules.lofi.p1":"Ít bit hơn và tần số lấy mẫu thấp hơn, từ 24 bit xuống 4 và từ 48 kHz xuống 1 kHz, với nhiễu dither, bộ lọc chống răng cưa, drive và một điều khiển Mix.","docs.modules.limiter.title":"Bộ giới hạn","docs.modules.limiter.p1":"Một bộ giới hạn true-peak: đầu ra không bao giờ vượt quá mức trần của nó, kể cả giữa các mẫu.","docs.modules.delay.title":"Độ trễ","docs.modules.delay.p1":"Năm đặc tính — Kỹ thuật số, Băng từ, Tương tự, Qua lại và Tiếng vọng ngắn. Thời gian được đặt bằng mili giây hoặc bằng giá trị nốt từ 1/64 đến hai ô nhịp, kể cả nốt liên ba và nốt chấm dôi, khớp nhịp với dự án của bạn. Bộ lọc trong vòng phản hồi, hạ âm khi giọng hát vang lên, và độ rộng; trên 100 % phản hồi, các lần lặp phồng lên rồi giữ nguyên thay vì vượt khỏi tầm kiểm soát.","docs.modules.reverb.title":"Vang","docs.modules.reverb.p1":"Năm đặc tính — Tấm, Phòng, Hội trường, Buồng vang và Không gian — với trễ trước, độ tắt từ 0.1 đến 20 giây, kích thước, giảm chấn, khuếch tán, điều biến và bộ lọc trên tín hiệu trả về. Độ tắt là thời gian để đuôi vang giảm 60 dB.","docs.modules.reversegate.title":"Cổng đảo ngược","docs.modules.reversegate.p1":"Vang ngược: sau mỗi âm, một làn vang phồng lên trong suốt độ dài cổng, từ 50 ms đến một giây, rồi tắt ngay. Nó không bao giờ nhìn trước, nên không thêm độ trễ và hoạt động cả khi bạn đang thu.","docs.modules.doubler.title":"Bộ nhân đôi","docs.modules.doubler.p1":"Biến một bản thu thành hai, ba hoặc bốn giọng, mỗi giọng trễ một chút, xê dịch nhẹ về thời gian và cao độ, và trải rộng trên trường stereo, với đặc tính Chặt và Rộng. Khi cộng về mono, nó vẫn gần với mức của chính giọng hát.","docs.modules.chorus.title":"Hợp xướng","docs.modules.chorus.p1":"Hiệu ứng hợp xướng hai giọng, một giọng lên cao độ trong khi giọng kia xuống, với tần suất, độ sâu, mix và drive; ở mức mix 50 %, nó giữ nguyên mức âm lượng và cộng về mono gọn gàng.","docs.modules.flanger.title":"Hiệu ứng flanger","docs.modules.flanger.p1":"Một độ trễ ngắn được quét lên xuống chậm rãi và hồi tiếp vào chính nó, với tốc độ, độ sâu, độ trễ, hồi tiếp và trộn; bên phải quét sớm hơn bên trái một phần tư chu kỳ, nên giọng mono được flanger trải khắp trường stereo.","docs.modules.phaser.title":"Hiệu ứng phaser","docs.modules.phaser.p1":"Một chuỗi 4, 8 hoặc 12 tầng all-pass được quét bởi một sóng chậm, hồi tiếp và trộn với giọng, với tốc độ, độ sâu, tần số, hồi tiếp, số tầng và trộn; bên phải quét sớm hơn bên trái một phần tư chu kỳ.","docs.modules.width.title":"Độ rộng","docs.modules.width.p1":"Thu hẹp hoặc mở rộng hình ảnh stereo, từ mono ở 0 % đến 200 %, mà không thay đổi tổng mono, cùng một độ trễ Haas lên đến 30 ms ở bên phải để trải rộng giọng hát mono.","docs.modules.autopan.title":"Tự động pan","docs.modules.autopan.p1":"Đưa giọng qua lại giữa hai bên theo sóng sin hoặc sóng tam giác, với tốc độ và độ sâu: đây là cân bằng, nên mỗi bên giữ âm thanh riêng, và ở giữa cả hai đi qua như khi vào; khi nghiêng về một bên, bên kia nhỏ dần, không bao giờ to hơn lúc vào.","docs.modules.shifter.title":"Dịch cao độ","docs.modules.shifter.p1":"Đưa giọng lên hoặc xuống tối đa hai quãng tám, formant được dịch riêng tối đa một quãng tám, với núm Mix: câu ad-lib thấp hơn một quãng tám. Giống Chỉnh cao độ, nó chờ 21 mili giây, hoặc 4 khi Tracking.","docs.project.p1":"Dự án của bạn giữ chuỗi, mọi mô-đun và núm, chế độ xem, bốn núm của chế độ Đơn giản, cả hai phía của phần so sánh và thứ mà Chỉnh cao độ lắng nghe. Nếu không đọc được cài đặt của dự án, nó sẽ mở với chuỗi mặc định và báo điều đó một lần, phía trên khu vực chính, cho đến khi bạn bỏ qua thông báo.","docs.agreement.p1":"Lần đầu mở, Takelight hiển thị thỏa thuận cấp phép và tuyên bố miễn trừ của nó. Cho đến khi bạn đồng ý, nó không làm gì ngoài việc cho âm thanh của bạn đi qua nguyên vẹn, nên từ chối không bao giờ làm một track bị câm.","docs.agreement.p2":"Câu trả lời của bạn được lưu trên máy tính của bạn và dùng chung cho mọi bản Takelight đang mở, trong mọi DAW và trong ứng dụng độc lập. Bạn có thể đọc lại thỏa thuận và chấp nhận bất cứ lúc nào.","docs.settings.p1":"Trong phần cài đặt, bạn chọn sáng hay tối, ngôn ngữ và những thứ khác. Lựa chọn thuộc về máy tính chứ không thuộc về dự án: chúng áp dụng cho mọi bản Takelight trên máy đó.","docs.language.p1":"Takelight và trang này dùng mười tám ngôn ngữ, với tiếng Ả Rập trình bày từ phải sang trái. Tên nghệ sĩ không bao giờ được dịch.","docs.disclaimer.p1":"Tên nghệ sĩ chỉ một phong cách, không hơn. Freally Takelight không liên kết với, không được ủng hộ, tài trợ hay chấp thuận bởi bất kỳ nghệ sĩ, nhà sản xuất, kỹ sư, hãng đĩa, ấn phẩm hay nhà làm plugin nào. Mọi tên và nhãn hiệu thuộc về chủ sở hữu, và hình ảnh, logo, chữ ký hay tác phẩm nghệ thuật của bất kỳ nghệ sĩ nào đều không được dùng ở đâu cả.","docs.disclaimer.p2":"Một chuỗi áp dụng xử lý; nó không thay đổi ai đang hát, và không chuỗi nào hứa hẹn một âm thanh cụ thể. Các mô-đun của Takelight là thiết kế riêng và không tự nhận là bất kỳ sản phẩm nào khác.","docs.disclaimer.p3":"Đây là bản tóm tắt. Takelight hiển thị toàn văn tuyên bố miễn trừ cùng thỏa thuận cấp phép của nó.","docs.privacy.p1":"Plugin và ứng dụng độc lập không bao giờ kết nối mạng: không tài khoản, không đo lường từ xa và không có mã mạng, thứ mà một cổng kiểm tra bản dựng từ chối. Giọng hát của bạn không bao giờ rời khỏi máy, và tệp tham chiếu bạn nạp cho A/B chỉ nằm trong bộ nhớ.","docs.privacy.p2":"Từ phiên bản 1.0, một trình trợ giúp riêng sẽ kiểm tra bản cập nhật và kích hoạt giấy phép của bạn — chỉ khi bạn yêu cầu. Nó không bao giờ tải xuống hay cài đặt gì.","docs.report.p1":"Hãy viết thư tới freallyproducts@gmail.com. Khi chính Takelight gặp lỗi, thông báo nó hiển thị sẽ có Báo cáo: nó mở trong trình duyệt của bạn một trang cho thấy tất cả những gì sẽ được gửi, và không gì rời khỏi máy cho đến khi bạn nhấn Gửi. Sau khi ứng dụng bị treo, lần khởi động tiếp theo cũng đưa ra lựa chọn tương tự.","roster.lede":"Mọi nghệ sĩ và mọi thể loại có chuỗi vocal trong plugin, theo từng thời kỳ.","roster.numbers.chains":"chuỗi vocal","roster.numbers.artists":"nghệ sĩ","roster.numbers.genres":"thể loại","roster.title":"Danh mục phong cách","roster.placeholder":"Tên, thể loại hoặc thời kỳ","roster.search":"Tìm","roster.col.type":"Loại","roster.all":"Tất cả","roster.artists":"Nghệ sĩ","roster.genres":"Thể loại","roster.col.name":"Phong cách","roster.col.era":"Thời kỳ","roster.col.roles":"Chuỗi","roster.col.genre":"Thể loại","roster.loading":"Đang tải danh mục phong cách…","roster.type.artist":"Nghệ sĩ","roster.type.genre":"Thể loại","roster.role.lead":"Giọng chính","roster.role.adlib":"Ad-lib","roster.role.double":"Double","roster.role.harmony":"Hòa âm","roster.role.fx":"FX","roster.era.decade":"Thập niên {year}","roster.era.modern":"Thời hiện đại","roster.era.classic":"Thời cổ điển","roster.era.record":"Thời {record}","roster.shown":"{shown} trên {total} khớp","roster.none":"Không có kết quả phù hợp.","roster.failed":"Không tải được danh mục phong cách. Hãy thử tải lại trang.","roster.file":"Trang này đang được mở dưới dạng tệp cục bộ, và trình duyệt từ chối tải danh mục phong cách từ một trang file://. Hãy mở trang qua HTTP.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.roster":"Danh mục","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.6.0 đã xong · tiếp theo là v0.7.0","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Mười ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Takelight, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.status.devVersion":"Đang phát triển · v0.6.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.roster":"<span class=\"hl-muted\">Mọi phong cách,</span> <span class=\"hl-bright\">trong một danh sách.</span>","kit.label.styles":"Phong cách","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Takelight, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","kit.zoom.close":"Đóng","changelog.2281e704f26e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-28\">2026-10-28</time></span><span class=\"release__title\">Đợt nghệ sĩ đầu tiên</span>","changelog.68aa0830d2bd":"Thêm bốn mươi nghệ sĩ, một chuỗi Giọng chính và một chuỗi Ad-lib cho mọi thể loại trong danh sách, và năm mô-đun mà các chuỗi mới cần, mỗi mô-đun có một thẻ vẽ ra những gì nó làm. Trang tài liệu liệt kê mọi chuỗi ở trang Danh mục phong cách.","changelog.6b02e0d363a4":"Đã thêm","changelog.9c62a6f2c632":"<strong>Thêm bốn mươi nghệ sĩ</strong> — mỗi người ở thời kỳ của một đĩa nhạc hoặc một thập niên, từ Adele đến Twice, và Cardi B cùng DaBaby có thêm cả chuỗi Ad-lib. Tìm một cái tên, như trước.","changelog.b471eaf5aa38":"<strong>Một chuỗi cho mọi thể loại</strong> — mỗi thể loại trong 73 thể loại của danh sách, từ afrobeats và amapiano đến UK garage và West Coast club, đều có chuỗi Giọng chính và chuỗi Ad-lib riêng; trap có cả hai cho thập niên 2000 và 2010. Một nghệ sĩ trong danh sách chưa có chuỗi riêng sẽ được gợi ý các chuỗi của thể loại mình.","changelog.285827d2c500":"<strong>EQ động</strong> — hai băng tần, mỗi băng dạng chuông hoặc kệ, chỉ cắt hoặc nâng khi giọng của bạn vượt ngưỡng của chúng, và chỉ xa đến mức dải của chúng cho phép. Thẻ của nó vẽ toàn bộ dải và vị trí hiện tại của từng băng.","changelog.05e32f63742f":"<strong>Đa dải</strong> — một bộ nén ba băng tần, trầm, trung và cao, được chia ở chỗ bạn chọn, mỗi băng có ngưỡng, tỷ lệ và độ lợi riêng. Khi không bớt gì, ba băng cộng lại thành giọng của bạn như ban đầu.","changelog.5ed52e2ef910":"<strong>Flanger và phaser</strong> — flanger quét một độ trễ ngắn so với giọng của bạn, còn phaser quét 4, 8 hoặc 12 tầng quanh một tần số bạn chọn; mỗi hiệu ứng có tốc độ, độ sâu, phản hồi và mức trộn riêng.","changelog.0ad4c2ec445b":"<strong>Tự động pan</strong> — di chuyển giọng của bạn giữa trái và phải, theo dạng sin hoặc tam giác, với tốc độ và độ sâu bạn chọn; bên mà nó rời đi sẽ nhỏ dần, và không bên nào bị nâng lên.","changelog.370c2eaa669e":"<strong>Cắt đỉnh</strong> — tính chất thứ năm cho Bão hòa: nó ép phẳng các đỉnh một cách dứt khoát, với một góc vừa đủ mềm để vẫn sạch.","changelog.d784579bd786":"<strong>Trang Danh mục phong cách</strong> — trang tài liệu liệt kê mọi nghệ sĩ và thể loại có chuỗi, theo từng thời kỳ, cùng các chuỗi mỗi bên có: Giọng chính, Ad-lib, FX.","changelog.2a6141e43be0":"Đã thay đổi","changelog.af0704823374":"<strong>Bốn delay rơi vào nốt móc đơn</strong> — các delay Ad-lib của thời hiện đại của Drake, R&amp;B cổ điển và trap thập niên 2010, cùng delay của chuỗi Giọng chính R&amp;B cổ điển, giờ lặp lại ở nốt móc đơn như dự định, chứ không phải móc đơn chấm dôi.","changelog.1231a0c0224a":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.6</span><time class=\"release__date\" datetime=\"2026-10-27\">2026-10-27</time></span><span class=\"release__title\">Thẻ trực quan</span>","changelog.ca7f81d415d0":"Thẻ của mỗi mô-đun giờ cho thấy nó làm gì, chứ không chỉ có núm: các EQ vẽ đường cong của chúng trên giọng hát của bạn khi nó phát, các bộ nén cho thấy giọng hát của bạn đang nằm ở đâu và chúng giảm đi bao nhiêu, còn các mô-đun khác vẽ các lần lặp, độ tắt, trường stereo và đường cong của chúng. Mỗi hình được tính từ chính phần toán học tạo nên âm thanh.","changelog.c885adad0ca5":"<strong>Thẻ EQ</strong> — EQ tham số, EQ bàn mixer và EQ chương trình vẽ đường cong của chúng trên phổ trực tiếp của giọng hát bạn, trước EQ (mờ) và sau EQ (sáng), với các đỉnh được giữ lại trong chốc lát. Mỗi băng tần có một chấm trên đường cong: kéo nó để dời tần số và độ lợi cùng lúc, lăn bánh xe chuột trên nó để chỉnh độ rộng, nhấp đúp để đưa nó về như cũ, hoặc dùng các phím mũi tên. Các chấm của EQ chương trình di chuyển giữa các tần số của nó, giống như các núm của nó, và các chấm Lớp A của EQ bàn mixer nằm trên các nấc mà nó dùng. Bộ khử âm xì vẽ băng tần mà nó lắng nghe và mức cắt mà nó tạo ra, còn Trim vẽ bộ lọc thông cao của nó.","changelog.e4155cb8a38e":"<strong>Thẻ bộ nén</strong> — Bộ nén quang, Bộ nén FET, Bộ nén VCA, Bộ nén vari-mu, Bộ nén Punch, Bộ ổn định mức giọng, Bộ cân mức tự động và Bộ giới hạn vẽ đường cong của chúng, mức đầu vào so với mức đầu ra, với một chấm ở vị trí giọng hát của bạn đang nằm trên đó lúc này và, bên dưới, mức giảm độ lợi của bốn giây gần nhất. Kéo ngưỡng dọc theo đường cong, hoặc dùng các phím mũi tên; thao tác này vặn núm đặt ngưỡng đó.","changelog.ec53ddb6a430":"<strong>Thẻ của Gate</strong> — đường cong của nó, và bên dưới là mức nó nghe được so với ngưỡng của nó trong bốn giây gần nhất, được tô bóng ở những chỗ nó đóng.","changelog.7c482c32b414":"<strong>Thẻ không gian</strong> — các lần lặp của Độ trễ trên một dòng thời gian theo phách và ô nhịp của dự án, mỗi lần lặp to đúng bằng mức phản hồi và bộ lọc để lại (ở Qua lại, bên trái nằm trên đường kẻ, bên phải nằm dưới); độ tắt của Vang — trễ trước, các phản xạ sớm và đuôi vang; độ dâng của Cổng đảo ngược; và trường stereo của Bộ nhân đôi, Hợp xướng và Độ rộng, nhìn từ trên xuống.","changelog.580a2bd46885":"<strong>Thẻ màu âm</strong> — Bão hòa, Bộ kích âm và Âm thanh lo-fi vẽ đường cong của chúng và, bên cạnh, các hài âm mà đường cong đó thêm vào giọng hát của bạn như nó đang có lúc này.","changelog.4aa1a07ba478":"<strong>Một lần kéo trên hai núm là một bước hoàn tác</strong> — dời chấm của một băng tần EQ sẽ thay đổi tần số và độ lợi của nó cùng lúc, và một lần Hoàn tác lấy lại cả lần kéo, dù bạn đã giữ yên nó bao lâu.","changelog.c64f3e0add84":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.5</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Input Check, ad-lib và preset</span>","changelog.f6741058398a":"Đặt mức trước khi thu, giữ các phiên bản riêng của bất kỳ chuỗi nào, và rút lại mọi thay đổi chỉ bằng một phím. Auto Key của Chỉnh cao độ giờ có thể tìm tông từ beat.","changelog.145f9c7721e2":"<strong>Input Check</strong> — nhấn Input Check trong rack rồi hát hoặc chơi phần sẽ thu trong mười giây; đèn thu âm sáng màu hổ phách trong lúc nó nghe. Sau đó nó hiển thị những gì nghe thấy (đỉnh, mức, độ to, mức nhiễu nền, tiếng ù, âm xì và tiếng bật hơi) và những gì đề xuất: Núm Đầu vào, cùng gate, thông cao và bộ khử âm xì mà chuỗi đã có. Không có gì thay đổi cho đến khi bạn nhấn Áp dụng, và mô-đun nào chuỗi không có sẽ báo như vậy — không có gì được thêm vào thay bạn. Nếu phần thu bị clip, nó sẽ bảo bạn giảm độ lợi trên sound card.","changelog.807271b61fd0":"<strong>Preset của bạn</strong> — Lưu preset… giữ chuỗi đúng như bạn đã định hình, dưới một cái tên bạn chọn, thành một tệp trong Tài liệu › Freally Takelight › Presets. Preset của tôi… tải, đổi tên, xuất và xóa chúng, và nhập một preset ai đó gửi cho bạn (tệp không phải preset sẽ bị từ chối, kèm lý do). Preset của bạn cũng xuất hiện trong ô tìm kiếm, dưới mục Preset của tôi, kèm chuỗi mà mỗi preset dựa trên. Khi chuỗi đó được cập nhật, preset của bạn đi theo nó và giữ các chỉnh sửa của bạn.","changelog.2110305b2ce9":"<strong>Hoàn tác và làm lại</strong> — mọi thay đổi đối với âm thanh, tối đa 100 bước: một núm (mỗi lần kéo là một bước), một mô-đun được thêm hoặc gỡ ra, đặc tính của nó, bỏ qua và solo, các mức gửi và fader, bốn núm lớn, Núm Đầu vào, một chuỗi hoặc preset được tải, và lần Áp dụng của Input Check. Dùng các mũi tên trên thanh trên cùng, hoặc Ctrl+Z và Ctrl+Shift+Z (cả Ctrl+Y; ⌘Z và ⌘⇧Z trên Mac) khi cửa sổ đang có tiêu điểm. Chế độ xem, chủ đề, ngôn ngữ và bản tham chiếu A/B không bao giờ bị hoàn tác, và tự động hóa trong DAW của bạn cũng vậy; chuyển giữa A và B sẽ bắt đầu lại lịch sử của phía đó từ đầu.","changelog.065bc3159eeb":"<strong>Núm Đầu vào</strong> — bên cạnh đồng hồ Vào, mức tín hiệu đi vào, từ −24 đến +24 dB. Input Check đặt nó, và DAW của bạn có thể tự động hóa nó.","changelog.0c42df2ca995":"<strong>Auto Key từ beat</strong> — Chỉnh cao độ có thể nghe một đầu vào sidechain: gửi beat của bạn vào sidechain của Freally Takelight và chọn <em>Lắng nghe: Sidechain</em> trên thẻ của Chỉnh cao độ, và Auto Key sẽ theo các hợp âm của beat thay vì giọng của bạn. Mỗi dự án nhớ lựa chọn của nó; Cài đặt đặt nó cho các dự án mới. Khi không có gì phát trên sidechain, Chỉnh cao độ nghe giọng hát của bạn và báo điều đó.","changelog.057d5c78c13a":"<strong>Hộp thoại Mở và Lưu thuộc về cửa sổ</strong> — chúng mở ra phía trước Freally Takelight và giữ nó ở phía sau cho đến khi bạn chọn xong.","changelog.adf9645e2b40":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-10-24\">2026-10-24</time></span><span class=\"release__title\">Ánh sáng đầu tiên — Drake &amp; trình duyệt chuỗi</span>","changelog.9befafdec87e":"Phiên bản hoàn chỉnh đầu tiên: tìm một nghệ sĩ, chọn một thời kỳ, nhấn play, và cả chuỗi vocal được nạp chỉ với một cú nhấp. Các thời kỳ của Drake và mười tám chuỗi thể loại xuất hiện, cùng bốn núm lớn để định hình chúng, một bản tham chiếu để so sánh, và một phiên bản thứ hai của chuỗi để so sánh cùng.","changelog.abd39e3e1804":"<strong>Trình duyệt chuỗi</strong> — gõ một nghệ sĩ hoặc một thể loại vào ô tìm kiếm (Ctrl+K, hoặc Cmd+K trên Mac), và các chuỗi được sắp theo thời kỳ và vai trò ngay khi bạn gõ, kể cả biệt danh. Khi ô trống, nó gợi ý các chuỗi bạn nạp gần đây nhất; với một nghệ sĩ chưa có trong thư viện, nó gợi ý một chuỗi thể loại. Mọi bước đều làm được bằng bàn phím.","changelog.6372ffc30569":"<strong>Drake</strong> — ba thời kỳ: thời So Far Gone (2009), thời Take Care (2011) và thời hiện đại (2016–2026), một chuỗi Giọng chính cho mỗi thời kỳ và một chuỗi Ad-lib cho thời hiện đại, cùng một chuỗi FX từ thời Take Care chỉ nằm trên các kênh trả về.","changelog.8def9e786270":"<strong>Mười tám chuỗi thể loại</strong> — một chuỗi Giọng chính và một chuỗi Ad-lib cho trap (thập niên 2000 và 2010), Chicago drill, emo rap, R&amp;B cổ điển, pop hiện đại, rock, country pop và reggaeton.","changelog.3370f1b4141c":"<strong>Chế độ Đơn giản</strong> — đèn thu âm, tên chuỗi, bốn núm lớn và đồng hồ Vào/Ra; Nâng cao hiển thị toàn bộ rack. Mỗi dự án nhớ nó được để ở chế độ nào, và Cài đặt cho bạn chọn phiên bản mới sẽ mở ở chế độ nào.","changelog.b4ff7f2e9dce":"<strong>Bốn núm</strong> — Chỉnh cao độ (giọng hát được chỉnh nhanh và tự nhiên đến đâu), Âm sắc (tối hơn hoặc sáng hơn, bộ khử âm xì đi theo), Không gian (mọi kênh gửi hiệu ứng cùng lúc) và Mức độ (cả chuỗi so với giọng hát khô của bạn). Khi Chỉnh cao độ, Âm sắc và Không gian ở giữa và Mức độ ở tối đa, chuỗi chạy như cách nó được tạo ra, và mọi chuỗi đều được nạp như vậy. DAW của bạn có thể tự động hóa cả bốn núm.","changelog.8988c7fcad46":"<strong>Bản tham chiếu A/B</strong> — mở một bài hát hoặc giọng hát đã hoàn thiện (WAV, AIFF, FLAC hoặc MP3, dài tối đa 20 phút), hoặc thả một tệp lên cửa sổ, và B phát nó từ vị trí hiện tại của DAW (từ đầu trong ứng dụng độc lập), chuyển tiếp mượt mà trong 20 ms và được cân bằng theo độ to của giọng hát bạn, để bạn đánh giá âm sắc chứ không phải mức âm lượng. Nó chỉ được giữ trong bộ nhớ: không bao giờ được lưu cùng dự án, một preset hay bất cứ đâu khác, và tệp trên ổ đĩa mạng sẽ bị từ chối.","changelog.41af758b9239":"<strong>So sánh chuỗi</strong> — hai phiên bản của chuỗi của bạn, A và B: B bắt đầu là bản sao của A, mỗi bên giữ những chỉnh sửa riêng, và một cú nhấp chuyển qua lại giữa chúng.","changelog.595ee8591a1b":"<strong>Dự án ghi nhớ</strong> — chuỗi, chế độ xem, các núm của chế độ Đơn giản và cả hai phía của phần so sánh được lưu cùng dự án. Một dự án không đọc được sẽ mở với chuỗi mặc định và báo điều đó một lần.","changelog.4794b815283f":"<strong>Con trỏ Freally</strong> — một vòng tròn với một chấm ở tâm, to lên khi đi qua bất cứ thứ gì bạn có thể nhấn.","changelog.3ad2505d4a1e":"<strong>Nút bật/tắt</strong> — mọi nút bật/tắt đều màu xám khi tắt, màu trắng khi con trỏ ở trên, và màu xanh Freally khi bật, dù con trỏ có ở trên hay không.","changelog.d526eacf003a":"<strong>Rack đầy sẽ báo cho bạn</strong> — một rack chứa được số núm bằng số núm Freally Takelight có thể điều khiển cùng lúc; mô-đun vượt quá giới hạn đó sẽ bị từ chối kèm một thông báo cho biết rack đã đầy.","changelog.81c6aadde005":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">Chỉnh cao độ</span>","changelog.ee8aa777588f":"Chỉnh cao độ đã đến: Chỉnh cao độ kéo giọng hát của bạn về các nốt trong tông của nó mà vẫn giữ formant, tự tìm ra tông, và hạ xuống vài mili giây độ trễ khi bạn thu âm; còn Dịch cao độ đưa một giọng lên hoặc xuống tối đa hai quãng tám.","changelog.e84a04d8e61c":"<strong>Chỉnh cao độ</strong> — chỉnh cao độ bằng xử lý tín hiệu cổ điển: Tốc độ chỉnh từ 0 ms (âm thanh cứng, bậc thang) đến 400 ms, Tự nhiên hóa để các nốt dài được thở, và Linh hoạt để giữ đoạn luyến và vibrato. Giọng bạn giữ được chất riêng, vì formant của nó vẫn ở nguyên chỗ.","changelog.1b908b3463cd":"<strong>Auto Key</strong> — Chỉnh cao độ nghe giọng hát của bạn và chốt tông sau khoảng bốn giây hát, giữ ở crômatic cho đến lúc đó. Khóa tông nó nghe được chỉ với một cú nhấp, hoặc chọn bất kỳ tông nào trong 24 tông, hoặc Crômatic.","changelog.539fbc62230d":"<strong>Đồ thị cao độ</strong> — bốn giây gần nhất của giọng bạn, cao độ khi hát và sau khi chỉnh, dưới nốt mà nó được kéo về.","changelog.0f378cb53cb4":"<strong>Tracking</strong> — khi DAW của bạn thu âm (hoặc khi bạn bật nó), Chỉnh cao độ chạy với độ trễ vài mili giây để bạn có thể hát qua chuỗi; khi mix, nó báo toàn bộ độ trễ để DAW của bạn giữ giọng hát khớp nhịp với beat.","changelog.2e82019ea87e":"<strong>Dịch cao độ</strong> — đưa một giọng lên hoặc xuống tối đa hai quãng tám, formant được dịch riêng tối đa một quãng tám, trộn với giọng gốc: câu ad-lib thấp hơn một quãng tám.","changelog.ba9e41780afd":"<strong>Đèn thu âm lắng nghe</strong> — nó sáng màu hổ phách khi Auto Key vẫn đang nghe để tìm tông.","changelog.e86e8d397ace":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-10-23\">2026-10-23</time></span><span class=\"release__title\">Không gian</span>","changelog.c223312c046d":"Bốn kênh trả về hiệu ứng xuất hiện, với độ trễ, vang, nhân đôi và độ rộng khớp nhịp với dự án của bạn, một phím Ném trên mỗi kênh trả về, và thêm bốn mô-đun cho insert.","changelog.eaa251798d7e":"<strong>Bốn kênh trả về hiệu ứng</strong> — A đến D, mỗi kênh được cấp từ cuối các insert qua núm Gửi của nó, có ba khe và fader riêng, hòa vào giọng hát khô trên đường vào bus vocal.","changelog.ebb30e23847f":"<strong>Ném</strong> — giữ phím Ném của một kênh trả về và giọng hát được ném vào đó, mức gửi ở 0 dB cho đến khi bạn thả ra. Ném A đến D cũng là tham số host, nên DAW của bạn có thể ghi lại một lần ném và phát lại.","changelog.39cab35a5560":"<strong>Độ trễ</strong> — Kỹ thuật số, Băng từ, Tương tự, Qua lại và Tiếng vọng ngắn, đặt bằng mili giây hoặc bằng giá trị nốt khớp nhịp với dự án của bạn, với bộ lọc trong vòng phản hồi, hạ âm khi giọng hát vang lên, và độ rộng.","changelog.d45fe717d01c":"<strong>Vang</strong> — Tấm, Phòng, Hội trường, Buồng vang và Không gian, với độ tắt từ 0.1 đến 20 giây; và <strong>Cổng đảo ngược</strong>, một tiếng vang ngược phồng lên mà không thêm độ trễ.","changelog.4db2c68f321a":"<strong>Bộ nhân đôi, Hợp xướng và Độ rộng</strong> — hai đến bốn giọng từ một bản thu, hiệu ứng hợp xướng hai giọng, và độ rộng stereo từ mono đến 200 % với độ trễ Haas.","changelog.8be315d62f9e":"<strong>Thêm bốn mô-đun cho insert</strong> — Bộ nén vari-mu với sáu hằng số thời gian, Bộ cân mức tự động, Bộ kích âm và Âm thanh lo-fi.","changelog.2d718978085b":"<strong>Khớp nhịp với dự án của bạn</strong> — một Độ trễ đặt theo giá trị nốt sẽ theo tempo của DAW, kể cả khi tempo thay đổi giữa bài.","changelog.e3c80cfe9d31":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-10-14\">2026-10-14</time></span><span class=\"release__title\">Joint, những mô-đun đầu tiên &amp; trang tài liệu</span>","changelog.521a85ebded1":"Rack xuất hiện: một Joint cho cả chuỗi vocal, mười ba mô-đun do Takelight tự thiết kế trên phần cứng được render, và đèn thu âm.","changelog.657c896de46f":"<strong>Joint</strong> — một rack theo thứ tự tín hiệu: tầng đầu hai khe, mười hai insert và một bus vocal bốn khe, DAW của bạn được cho biết độ trễ của nó, và Mức độ pha trộn cả chuỗi với giọng hát khô.","changelog.44955680f91b":"<strong>Thay đổi không tiếng tách</strong> — thêm, gỡ và đổi mô-đun khi bài đang chạy: rack mới được chuẩn bị tách khỏi âm thanh và chuyển vào trong 30 mili giây, một đặc tính mới được chuyển tiếp mượt mà, và mọi núm đều lướt nhẹ.","changelog.5883cafdd389":"<strong>Mười ba mô-đun</strong> — Trim; EQ tham số, EQ bàn mixer và EQ chương trình; bộ nén quang, FET, VCA và Punch; Bộ ổn định mức giọng; Bộ khử âm xì; Gate; Bão hòa; và một Bộ giới hạn true-peak.","changelog.da4d68a37948":"<strong>Màn hình rack</strong> — mỗi mô-đun là một thẻ phần cứng được render, với đặc tính, Bỏ qua, Solo và mức giảm độ lợi, mọi điều khiển đều dùng được từ bàn phím, bằng 18 ngôn ngữ.","changelog.19b404056636":"<strong>Tự động hóa</strong> — 24 tham số host của mỗi khe điều khiển các nút điều khiển của mô-đun theo thứ tự, nên danh sách tham số không bao giờ thay đổi.","changelog.93ce19272231":"<strong>Đèn thu âm và đồng hồ đo</strong> — chiếc đèn phòng thu, được render trong Blender ở bản tối và sáng, sáng xanh lục khi có mô-đun trong rack và giọng của bạn đang vào, và nháy đỏ khi bị clip; đồng hồ Vào và Ra có đèn clip.","changelog.54bf2d68a5db":"<strong>Báo cáo</strong> — khi chính Takelight gặp lỗi, hoặc sau khi ứng dụng bị treo, một trang trong trình duyệt của bạn cho thấy tất cả những gì một báo cáo sẽ gửi, và không gì được gửi cho đến khi bạn nhấn Gửi.","changelog.42b61e5ef13f":"<strong>Trang tài liệu, hoàn chỉnh</strong> — trang chủ, tính năng, sách hướng dẫn, nhật ký thay đổi và bậc thang phiên bản, bằng 18 ngôn ngữ.","changelog.2178abb38e7d":"<strong>Thỏa thuận cấp phép nay là phiên bản 2</strong>, nên Takelight yêu cầu bạn chấp nhận nó thêm một lần. Thỏa thuận và tuyên bố miễn trừ đều ngắn hơn và dễ hiểu hơn.","changelog.e6a2eb660b78":"<strong>Bớt một thiết lập</strong> — những chấm màu bên cạnh giá trị đã không còn, và thiết lập của chúng cũng vậy. Phần ghi công chỉ liệt kê các thông báo giấy phép.","changelog.5758b5c96327":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.1</span><time class=\"release__date\" datetime=\"2026-10-13\">2026-10-13</time></span><span class=\"release__title\">Cài đặt, vẽ lại</span>","changelog.898338328178":"<strong>Cài đặt, vẽ lại</strong> — mở từ bánh răng trên thanh trên cùng và đóng bằng dấu ×; chủ đề là công tắc tối/sáng với mặt trăng và mặt trời, mỗi lựa chọn ngắn là một điều khiển phân đoạn với con trượt, và các văn bản dài trong Giới thiệu là một danh sách các hàng.","changelog.5c7b3a54f6e0":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-10-12\">2026-10-12</time></span><span class=\"release__title\">Nền móng, xương sống CI và lộ trình phát hành</span>","changelog.e7f1a5798692":"Một Freally Takelight trống, nạp được trong host, cho âm thanh đi qua, và đã có sẵn mọi cổng kiểm tra, cả hai nhánh CI và lộ trình phát hành trước khi có bất kỳ tính năng nào.","changelog.82a7fc560af2":"<strong>Plugin trống, ở mọi định dạng</strong> — CLAP từ nih-plug, VST3 và AU được clap-wrapper chiếu ra từ cùng một tệp nhị phân, cùng một ứng dụng độc lập. Đầu vào mono và stereo, đầu ra stereo; âm thanh đi qua nguyên vẹn.","changelog.9dc28fd94514":"<strong>Kho tham số</strong> — đầu vào, đầu ra, mức độ, bypass, tracking, ba macro, bốn throw và 30 khe, mỗi khe 24 tham số chung, để việc nạp một chuỗi không bao giờ thay đổi danh sách tham số của host.","changelog.7a8b66c5fe5a":"<strong>Khung trình chỉnh sửa</strong> — bộ giao diện Freally ở chế độ tối và sáng, EULA và tuyên bố miễn trừ ở lần chạy đầu, Cài đặt và Giới thiệu, 18 ngôn ngữ với bố cục từ phải sang trái.","changelog.ec039c3098d0":"<strong>Các cổng kiểm tra</strong> — không AI, không mạng, không mã vay mượn, tên sản phẩm và từ cấm, không tải xuống trước 1.0, bậc thang phiên bản, giấy phép, các crate dùng chung, bộ giao diện và hình ảnh phần cứng, ngôn ngữ và CSS logic, độ lệch binding và không cấp phát bộ nhớ trên luồng âm thanh.","changelog.872b0df7744d":"<strong>CI tự lưu trữ</strong> — <code>npm run ci:local</code> (Windows) và <code>npm run ci:linux</code> (Docker Desktop), một danh sách kiểm tra; Playwright với trình chỉnh sửa và với ứng dụng độc lập thật.","changelog.5cbd8ff53c0a":"<strong>Lộ trình phát hành</strong> — <code>npm run release:local</code> dựng đúng tag, kiểm tra các gói, ghi thư mục phát hành kèm mã băm, dọn <code>target/</code> chỉ còn thư mục đó và cài VST3 cùng CLAP qua một lời nhắc UAC duy nhất.","changelog.4e9699d53d2d":"<strong>Khung trang tài liệu</strong> và khung dữ liệu chuỗi (<code>tlc validate</code>, <code>tlc import-roster</code>)."};
